(async()=>{'use strict';
const $=s=>document.querySelector(s),L=ClawLife,s=L.create(Math.random),reduce=matchMedia('(prefers-reduced-motion: reduce)');
let lastUI='';
let accumulator=0,depthDirection=0,depthPointer=null,depthVelocity=0;
const aimKeys=new Set();
let progress=load(),paused=false,last=0,clock=0,lastPhase='',swing=0,previousX=s.x,context=null,saveFailed=false,graphicsBlocked=false,reportedDrawError=false;
function load(){try{return L.decode(localStorage.getItem(L.KEY))}catch{return L.decode(null)}}
function writeProgress(change){let next;if(saveFailed)next=progress;else try{const raw=localStorage.getItem(L.KEY);next=raw?L.decode(raw):progress;}catch{next=progress}const result=change(next);if(result===false){progress=next;updateCollection();return false;}progress=next;try{localStorage.setItem(L.KEY,JSON.stringify(progress));saveFailed=false;}catch{saveFailed=true;}updateCollection();return true;}
// Center each drawing by its visible artwork bounds, not its original SVG canvas.
const plushFrames={frog:'-44 -38 88 88',koi:'-56 -50 102 102',chick:'-47.833 -48.667 96.667 96.667',bunny:'-62.010 -75.020 124.020 124.020',dumpling:'-46 -45.990 94 94',cat:'-45.290 -43 92 92',moonfox:'-37.235 -45 94 94'};
function updateCollection(){const owned=L.TYPES.filter(t=>progress.collection[t.id]);$('#plush-list').innerHTML=owned.length?owned.map(t=>`<div class="plush-row" data-secret="${t.secret===true}"><span class="plush-picture" role="img" aria-label="${t.name}"><svg viewBox="${plushFrames[t.id]}" aria-hidden="true">${ClawArt.plush(t.id)}</svg></span><b class="plush-quantity" aria-label="${progress.collection[t.id]} collected">×${progress.collection[t.id]}</b><button type="button" data-sell-type="${t.id}" aria-label="Sell one ${t.name} for ${L.sellValue(t.id)} coins">Sell 1 <small>+${L.sellValue(t.id)} coins</small></button></div>`).join(''):'<p class="inventory-empty">No plushies yet.</p>';$('#coin-balance').textContent=progress.coins;$('#sound').setAttribute('aria-pressed',progress.sound);$('#sound').textContent=progress.sound?'Sound on':'Sound off';$('#save-note').textContent=saveFailed?'Your coins and plushies are in memory; this browser could not save them.':'Your coins and plushies stay saved in this browser.';}
function status(message,win=false){$('#status').textContent=message;$('#status').dataset.win=win;}
function sound(kind){if(!progress.sound)return;try{context||=new (window.AudioContext||window.webkitAudioContext)();context.resume();const notes=kind==='win'?[523.25,659.25,783.99]:kind==='drop'?[261.63]:[329.63,293.66];notes.forEach((frequency,i)=>{const t=context.currentTime+i*.13,osc=context.createOscillator(),gain=context.createGain();osc.type='sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.035,t+.025);gain.gain.exponentialRampToValueAtTime(.0001,t+.6);osc.connect(gain);gain.connect(context.destination);osc.start(t);osc.stop(t+.65);});}catch{}}
function setControls(open){if(!open&&!$('#controller-body').hidden)resetAim();document.body.classList.toggle('controls-open',open);$('#controller-body').hidden=!open;$('#toggle-controls').setAttribute('aria-expanded',String(open));$('#toggle-controls').setAttribute('aria-label',`${open?'Close':'Open'} arcade controls`);}
$('#toggle-controls').onclick=()=>setControls($('#controller-body').hidden);$('#close-controls').onclick=()=>{setControls(false);$('#toggle-controls').focus({preventScroll:true});};document.addEventListener('pointerdown',e=>{if(!e.target.closest('.arcade-controller,.depth-control'))setControls(false);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#controller-body').hidden){setControls(false);$('#toggle-controls').focus({preventScroll:true});}});
$('#plush-list').onclick=e=>{const button=e.target.closest('[data-sell-type]');if(!button)return;let sold=null;if(writeProgress(p=>{sold=[...p.friends].reverse().find(f=>f.type===button.dataset.sellType);return sold?L.sell(p,sold.id):false;})){const type=L.TYPES.find(t=>t.id===sold.type);status(`One ${type.name} found a new home. +${L.sellValue(sold.type)} coins.`,true);if(view){if(progress.lastKept)view.presentPrize(progress.lastKept);else view.clearPrize();render();}}};
let view,physics;
try{const [{ClawScene},{ClawPhysics}]=await Promise.all([import('./claw-scene.js?v=20'),import('./claw-physics.js?v=17')]);physics=await ClawPhysics.create(s);view=new ClawScene($('.scene-stage'));}catch(error){console.error('Claw scene could not start',error);$('.loading').textContent='The 3D arcade could not start in this browser. Try a browser with hardware acceleration enabled.';status('Your collection is still saved.');updateCollection();return;}
function drawScene(){try{view.draw(s,{clock,swing,reduced:reduce.matches,still:paused});if(graphicsBlocked){graphicsBlocked=false;status(s.phase==='scanning'?'The claw is moving. Drop when it lines up.':'Picking up where we left off.');}reportedDrawError=false;}catch(error){graphicsBlocked=true;if(!reportedDrawError){console.error('Claw view interrupted',error);reportedDrawError=true;}status('The view is catching up. Your turn is paused.');}}
function render(){const ui=[s.phase,paused,progress.coins,Math.ceil(s.scanRemaining),s.depthAim<-.25?'Back':s.depthAim>.25?'Front':'Middle'].join('|');if(ui===lastUI){drawScene();return;}lastUI=ui;$('#turn-time').textContent=s.phase==='scanning'?Math.ceil(s.scanRemaining):s.phase==='idle'?L.AIM_SECONDS:'—';$('#turn-clock').dataset.active=String(s.phase==='scanning');$('#turn-clock').dataset.urgent=String(s.phase==='scanning'&&s.scanRemaining<=5);document.querySelectorAll('[data-depth]').forEach(b=>b.disabled=paused||s.phase!=='scanning');$('#depth-position').textContent=s.depthAim<-.25?'Back':s.depthAim>.25?'Front':'Middle';if(paused||s.phase!=='scanning')resetAim();$('#insert').disabled=paused||s.phase!=='idle'||progress.coins<L.TURN_COST;$('#drop').disabled=paused||s.phase!=='scanning';$('#insert span').textContent=s.phase==='idle'?(progress.coins<L.TURN_COST?'No coins':'Insert · 1'):s.phase==='coin'?'Coin in…':'In play';$('#drop span').textContent=paused?'Paused':['idle','coin','scanning'].includes(s.phase)?'Catch':'Catching…';if(s.phase!==lastPhase){if(s.phase==='scanning')status('The claw is moving. Drop when it lines up.');if(s.phase==='down')status(s.autoDropped?'Time’s up. Down we go.':'Down we go.');if(s.phase==='up')status(s.caught?'Hold on, little one.':'Just missed. Another coin, another chance.');if(s.phase==='carry')status('A little friend, on the way.');if(s.phase==='idle'&&lastPhase==='up')sound('miss');lastPhase=s.phase;}drawScene();}
function insert(){if(paused||graphicsBlocked||s.phase!=='idle')return;if(!writeProgress(p=>L.spend(p))){status(progress.friends.length?'No coins left. Sell a plushie in the controls for more coins.':'No coins left. Your balance stays saved here.');render();return;}if(L.insert(s)){view.clearPrize();status('One little coin. The carriage is waking up.');sound('drop');render();}}
function drop(){if(paused)return;if(L.drop(s,physics)){sound('drop');render();}}
function claim(){if(!s.pending)return;const prize=s.pending;s.pending=null;writeProgress(p=>L.collect(p,prize.type));const type=L.TYPES.find(t=>t.id===prize.type);view.presentPrize(prize.type);status(type.secret?`${type.name}, a secret little friend. A rare catch, yours to keep.`:`${type.name} found a soft landing. Added to your plushies.`,true);sound('win');}
$('.scene-stage').addEventListener('machine-action',e=>{if(e.detail==='insert')insert();else if(e.detail==='drop')drop();});$('.scene-stage').addEventListener('scene-lost',()=>{paused=true;$('#pause').textContent='Resume';document.body.classList.add('paused');status('The view paused. It will resume when graphics are ready.');render();});$('.scene-stage').addEventListener('scene-restored',()=>{status('The view is ready. Tap Resume to continue.');render();});$('#insert').onclick=insert;$('#drop').onclick=drop;$('#drop').addEventListener('pointerdown',event=>{if(event.button!==0||$('#drop').disabled)return;event.preventDefault();$('#drop').focus({preventScroll:true});drop();});
function stopDepth(event){if(event&&event.pointerId!==depthPointer)return;depthDirection=0;depthPointer=null;if(!aimKeys.size)depthVelocity=0;}
function resetAim(){stopDepth();aimKeys.clear();depthVelocity=0;}
document.querySelectorAll('[data-depth]').forEach(button=>{const nudge=()=>{if(!paused&&L.aimDepth(s,s.depthAim+Number(button.dataset.depth)*.12))render();};button.addEventListener('pointerdown',event=>{if(event.button!==0||button.disabled||depthPointer!==null)return;event.preventDefault();depthPointer=event.pointerId;depthDirection=Number(button.dataset.depth);button.setPointerCapture(event.pointerId);button.focus({preventScroll:true});nudge();});button.addEventListener('pointerup',stopDepth);button.addEventListener('pointercancel',stopDepth);button.addEventListener('lostpointercapture',stopDepth);button.addEventListener('click',event=>{if(event.detail===0)nudge();});});window.addEventListener('pointerup',stopDepth);window.addEventListener('pointercancel',stopDepth);window.addEventListener('blur',resetAim);
document.addEventListener('keyup',e=>{aimKeys.delete(e.key);if(!aimKeys.size&&!depthDirection)depthVelocity=0;});
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,a,[contenteditable=true]'))return;if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();if(!paused&&s.phase==='scanning'&&!aimKeys.has(e.key)){aimKeys.add(e.key);L.aimDepth(s,s.depthAim+(e.key==='ArrowUp'?-.025:.025));}return;}if(e.code==='Space'&&s.phase==='scanning'){e.preventDefault();if(!e.repeat)drop();return;}const button=e.target.closest('button');if(button){if((button.id==='drop'&&(e.code==='Space'||e.key==='Enter'))||(button.id==='insert'&&s.phase==='scanning'&&e.code==='Space')){e.preventDefault();if(!e.repeat)drop();}return;}if(e.code==='Space'){e.preventDefault();if(!e.repeat)drop();}if(e.key==='Enter'){e.preventDefault();if(!e.repeat)insert();}});
$('#pause').onclick=()=>{paused=!paused;document.body.classList.toggle('paused',paused);$('#pause').textContent=paused?'Resume':'Pause';$('#pause').setAttribute('aria-pressed',paused);status(paused?'A quiet moment. Resume whenever you’re ready.':s.phase==='idle'?'Insert a coin whenever you’re ready.':s.phase==='scanning'?'The claw is moving. Time your drop.':'Picking up where we left off.');render();};
$('#sound').onclick=()=>{writeProgress(p=>p.sound=!p.sound);if(progress.sound)sound('drop');};
window.addEventListener('storage',e=>{if(e.key===L.KEY){progress=load();updateCollection();if(view)render();}});
document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden){resetAim();context?.suspend();}});
// Keep input and future frames alive even if the 3D renderer fails during a turn.
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.15,Math.max(0,(now-last)/1000||0));last=now;if(document.hidden){accumulator=0;return;}if(paused){accumulator=0;drawScene();return;}if(graphicsBlocked){drawScene();return;}clock+=dt;if(s.phase==='idle'&&!physics.isMoving()){accumulator=0;s.physicsMoving=false;drawScene();return;}accumulator+=dt;while(accumulator>=1/60){if(s.phase==='scanning'){const direction=depthDirection||Number(aimKeys.has('ArrowDown'))-Number(aimKeys.has('ArrowUp'));const targetSpeed=direction*.95;depthVelocity+=(targetSpeed-depthVelocity)*(1-Math.exp(-12/60));if(direction)L.aimDepth(s,s.depthAim+depthVelocity/60);else depthVelocity=0;}L.update(s,1/60,physics,Math.random);physics.step(s,1/60);accumulator-=1/60;claim();}s.physicsMoving=physics.isMoving();if(s.phase!=='idle'||s.phase!==lastPhase)render();else drawScene();}
updateCollection();if(progress.lastKept)view.presentPrize(progress.lastKept);render();requestAnimationFrame(frame);
})();
